package com.quetzalcharges;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class QuetzalChargesPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(QuetzalChargesPlugin.class);
		RuneLite.main(args);
	}
}

package com.quetzalcharges;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The charge and rumour messages are the only authoritative sources the plugin has, so a regex
 * mistake here silently breaks the whole plugin. These run without a client.
 */
public class ChatParsingTest
{
	@Test
	public void parsesPluralCharges()
	{
		assertEquals(Integer.valueOf(4),
			QuetzalChargesPlugin.parseChargesMessage("Your quetzal whistle has 4 charges remaining."));
	}

	@Test
	public void parsesMessageObservedInGame()
	{
		// Verbatim from a live client, 2026-08-07.
		assertEquals(Integer.valueOf(7),
			QuetzalChargesPlugin.parseChargesMessage("Your quetzal whistle has 7 charges remaining."));
	}

	@Test
	public void parsesSingularCharge()
	{
		assertEquals(Integer.valueOf(1),
			QuetzalChargesPlugin.parseChargesMessage("Your quetzal whistle has 1 charge remaining."));
	}

	@Test
	public void parsesZeroAndMaxCharges()
	{
		assertEquals(Integer.valueOf(0),
			QuetzalChargesPlugin.parseChargesMessage("Your quetzal whistle has 0 charges remaining."));
		assertEquals(Integer.valueOf(50),
			QuetzalChargesPlugin.parseChargesMessage("Your quetzal whistle has 50 charges remaining."));
	}

	@Test
	public void ignoresUnrelatedMessages()
	{
		assertNull(QuetzalChargesPlugin.parseChargesMessage(
			"Your current rumour target is a grey chinchompa."));
		assertNull(QuetzalChargesPlugin.parseChargesMessage(
			"Unfortunately, large birds can't just fly you to Varlamore from here."));
		assertNull(QuetzalChargesPlugin.parseChargesMessage(
			"Your dodgy necklace has 4 charges left."));
	}

	@Test
	public void parsesTheRumourMessageTheWikiQuotes()
	{
		final String message = "Your current rumour target is a grey chinchompa. You'll need to bring "
			+ "back some of its fur. Cervus was the source of the rumour.";

		assertEquals("grey chinchompa", QuetzalChargesPlugin.parseRumourTarget(message));
		assertEquals("Cervus", QuetzalChargesPlugin.parseRumourHunter(message));
	}

	@Test
	public void parsesTargetsWhateverArticleTheGameUses()
	{
		// "an" for a vowel, and the hyphen in a kebbit name must survive -- it is inside the group,
		// not a boundary.
		assertEquals("embertailed jerboa", QuetzalChargesPlugin.parseRumourTarget(
			"Your current rumour target is an embertailed jerboa. Gilman was the source of the rumour."));
		assertEquals("sabre-toothed kebbit", QuetzalChargesPlugin.parseRumourTarget(
			"Your current rumour target is a sabre-toothed kebbit. Aco was the source of the rumour."));
	}

	@Test
	public void readsTheTargetEvenWhenNoHunterIsNamed()
	{
		// The two sentences are matched independently precisely so that losing one keeps the other.
		final String message = "Your current rumour target is a herbiboar. You'll need to bring back "
			+ "some of its tuft.";

		assertEquals("herbiboar", QuetzalChargesPlugin.parseRumourTarget(message));
		assertNull(QuetzalChargesPlugin.parseRumourHunter(message));
	}

	@Test
	public void chargeAndRumourMessagesNeverParseAsEachOther()
	{
		assertNull(QuetzalChargesPlugin.parseRumourTarget(
			"Your quetzal whistle has 7 charges remaining."));
		assertNull(QuetzalChargesPlugin.parseChargesMessage(
			"Your current rumour target is a grey chinchompa. You'll need to bring back some of its "
				+ "fur. Cervus was the source of the rumour."));
	}

	@Test
	public void recognisesTheNoRumourReply()
	{
		// Confirmed in-game 2026-08-07. It shares no wording with the assigned-rumour message, so the
		// target parser cannot latch onto it -- but it is a stated fact, so it clears a stale rumour.
		final String message = "You do not have an active rumour right now";

		assertTrue(QuetzalChargesPlugin.isNoRumourMessage(message));
		assertNull(QuetzalChargesPlugin.parseRumourTarget(message));

		assertFalse(QuetzalChargesPlugin.isNoRumourMessage(
			"Your current rumour target is a grey chinchompa."));
		assertFalse(QuetzalChargesPlugin.isNoRumourMessage(
			"Your quetzal whistle has 7 charges remaining."));
	}

	@Test
	public void capitalisesOnlyTheFirstLetter()
	{
		// Title-casing would produce "Sabre-Toothed Kyatt", a spelling the game never uses.
		assertEquals("Sabre-toothed kyatt", QuetzalChargesPlugin.capitalise("sabre-toothed kyatt"));
		assertEquals("", QuetzalChargesPlugin.capitalise(""));
	}

	@Test
	public void formatsInfiniteAndUnknown()
	{
		assertEquals("∞", QuetzalChargesPlugin.formatCharges(QuetzalWhistle.PERFECTED_INFINITE, 0));
		assertEquals("?", QuetzalChargesPlugin.formatCharges(
			QuetzalWhistle.PERFECTED, QuetzalChargesPlugin.UNKNOWN));
		assertEquals("12", QuetzalChargesPlugin.formatCharges(QuetzalWhistle.PERFECTED, 12));
	}

	@Test
	public void mapsItemIdsToTiers()
	{
		assertEquals(QuetzalWhistle.BASIC, QuetzalWhistle.byItemId(29271));
		assertEquals(QuetzalWhistle.ENHANCED, QuetzalWhistle.byItemId(29273));
		assertEquals(QuetzalWhistle.PERFECTED, QuetzalWhistle.byItemId(29275));
		assertEquals(QuetzalWhistle.PERFECTED_INFINITE, QuetzalWhistle.byItemId(33120));
		assertNull(QuetzalWhistle.byItemId(995));
	}

	@Test
	public void tiersAreOrderedWorstToBest()
	{
		// applyUpgrade compares ordinals to decide which way charges move.
		assertEquals(5, QuetzalWhistle.BASIC.getMaxCharges());
		assertEquals(20, QuetzalWhistle.ENHANCED.getMaxCharges());
		assertEquals(50, QuetzalWhistle.PERFECTED.getMaxCharges());
	}
}

