package com.quetzalcharges;

import static com.quetzalcharges.MeatUse.UNUSED;
import static com.quetzalcharges.MeatUse.USED;
import static com.quetzalcharges.MeatUse.WASTEFUL;
import static org.junit.Assert.assertArrayEquals;
import org.junit.Test;

/**
 * The consumption model, checked against observed behaviour rather than against the wiki -- the wiki
 * only says charging "fills to the cap and stops", which is true and hides the part that matters.
 */
public class MeatPredictionTest
{
	@Test
	public void takesInSlotOrderRatherThanTakingTheMeatThatFits()
	{
		// Observed: needing 3 with meat ordered 1, 1, 3, 3, Pitri takes the 1, the 1 and then a 3 --
		// five charges of meat to deliver three -- instead of taking a single 3.
		assertArrayEquals(
			new MeatUse[]{USED, USED, WASTEFUL, UNUSED},
			QuetzalChargesPlugin.predictUse(new int[]{1, 1, 3, 3}, 3));
	}

	@Test
	public void marksTheOvershootingMeatOnly()
	{
		// Six raw graahk at 2 charges each, needing 3: the first is fully used, the second overshoots
		// by one, and the rest are never reached.
		assertArrayEquals(
			new MeatUse[]{USED, WASTEFUL, UNUSED, UNUSED, UNUSED, UNUSED},
			QuetzalChargesPlugin.predictUse(new int[]{2, 2, 2, 2, 2, 2}, 3));
	}

	@Test
	public void landingExactlyOnTheRequirementWastesNothing()
	{
		assertArrayEquals(
			new MeatUse[]{USED, USED, UNUSED},
			QuetzalChargesPlugin.predictUse(new int[]{2, 2, 2}, 4));
	}

	@Test
	public void reorderingChangesTheVerdict()
	{
		// The same meat needing the same 3 charges, with the 3 moved to the front: one meat instead
		// of three, and nothing wasted. This is the saving the overlay exists to make visible.
		assertArrayEquals(
			new MeatUse[]{USED, UNUSED, UNUSED, UNUSED},
			QuetzalChargesPlugin.predictUse(new int[]{3, 1, 1, 3}, 3));
	}

	@Test
	public void everythingIsUsedWhenTheMeatRunsOutFirst()
	{
		assertArrayEquals(
			new MeatUse[]{USED, USED, USED},
			QuetzalChargesPlugin.predictUse(new int[]{1, 2, 3}, 20));
	}

	@Test
	public void nothingIsPredictedWhenTheWhistleIsAlreadyFull()
	{
		// Not "every meat unused" -- no verdict at all, so the overlay draws nothing. A full whistle
		// and a whistle that fills before reaching this meat are different facts, and painting both
		// red made the common case (walking around full) look like a warning.
		assertArrayEquals(
			new MeatUse[0],
			QuetzalChargesPlugin.predictUse(new int[]{2, 3}, 0));
	}

	@Test
	public void nothingIsPredictedWhenTheStoredCountExceedsTheCap()
	{
		// A negative shortfall is reachable: a count stored against one tier can outlive a change to
		// the whistle being held. It means the same thing as full.
		assertArrayEquals(
			new MeatUse[0],
			QuetzalChargesPlugin.predictUse(new int[]{2, 3}, -4));
	}

	@Test
	public void emptySlotsCarryNoVerdictAndDoNotBreakTheOrder()
	{
		// Zeroes are non-meat slots. They must be skipped without consuming the run, so a gap in the
		// inventory does not shift which meat overshoots.
		assertArrayEquals(
			new MeatUse[]{null, USED, null, WASTEFUL, null, UNUSED},
			QuetzalChargesPlugin.predictUse(new int[]{0, 1, 0, 3, 0, 2}, 2));
	}
}

