package com.quetzalcharges;

import java.awt.Color;
import java.awt.image.BufferedImage;
import lombok.Getter;
import net.runelite.client.ui.overlay.infobox.Counter;

/**
 * Counter infobox for the whistle currently held. {@link Counter} stores an int count, which the
 * infinite whistle and the unknown state cannot express, so both text and color are overridden.
 */
@Getter
class QuetzalChargesInfobox extends Counter
{
	private final QuetzalChargesPlugin plugin;
	private final QuetzalWhistle whistle;
	private final int charges;

	QuetzalChargesInfobox(
		QuetzalChargesPlugin plugin,
		BufferedImage image,
		QuetzalWhistle whistle,
		int charges,
		String tooltip)
	{
		super(image, plugin, Math.max(charges, 0));
		this.plugin = plugin;
		this.whistle = whistle;
		this.charges = charges;
		setTooltip(tooltip);
	}

	@Override
	public String getText()
	{
		return QuetzalChargesPlugin.formatCharges(whistle, charges);
	}

	@Override
	public Color getTextColor()
	{
		return plugin.getColor(whistle, charges);
	}
}

