package com.quetzalcharges;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup(QuetzalChargesConfig.GROUP)
public interface QuetzalChargesConfig extends Config
{
	String GROUP = "quetzal-whistle-charges";

	@ConfigSection(
		name = "Colors",
		description = "Colors used for the charge count.",
		position = 90
	)
	String colorSection = "colors";

	@ConfigItem(
		keyName = "showInventoryOverlay",
		name = "Inventory overlay",
		description = "Draw the remaining charges on the whistle in the inventory and bank.",
		position = 1
	)
	default boolean showInventoryOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showInfobox",
		name = "Infobox",
		description = "Show an infobox with the remaining charges while a whistle is in the inventory.",
		position = 2
	)
	default boolean showInfobox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRechargeHelper",
		name = "Recharge helper",
		description = "Add the charge value of hunter meat in the inventory to the infobox tooltip.",
		position = 3
	)
	default boolean showRechargeHelper()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showMeatValues",
		name = "Meat charge values",
		description = "Draw each hunter meat's charge value on it, colored by whether the next recharge "
			+ "would use it. Only shown while holding a whistle whose count is known.",
		position = 4
	)
	default boolean showMeatValues()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRumour",
		name = "Current rumour",
		description = "Add your current hunter rumour to the infobox tooltip. Reported by the whistle's "
			+ "Rumour option, so it updates whenever you use it.",
		position = 5
	)
	default boolean showRumour()
	{
		return true;
	}

	@Range(min = 0, max = 50)
	@ConfigItem(
		keyName = "lowChargeThreshold",
		name = "Low charge threshold",
		description = "Charges at or below this count are shown in the low-charge color.",
		position = 6
	)
	default int lowChargeThreshold()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "lowChargeNotification",
		name = "Low charge notification",
		description = "Send a notification the first time charges drop to the low charge threshold.",
		position = 7
	)
	default Notification lowChargeNotification()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "chargeColor",
		name = "Charges",
		description = "Color of the count when charges are above the low threshold.",
		position = 91,
		section = colorSection
	)
	default Color chargeColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "lowChargeColor",
		name = "Low charges",
		description = "Color of the count when charges are at or below the low threshold.",
		position = 92,
		section = colorSection
	)
	default Color lowChargeColor()
	{
		return Color.YELLOW;
	}

	@ConfigItem(
		keyName = "emptyColor",
		name = "No charges",
		description = "Color of the count when the whistle is empty.",
		position = 93,
		section = colorSection
	)
	default Color emptyColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "meatUsedColor",
		name = "Meat: fully used",
		description = "Color of a meat's value when the next recharge takes it and wastes nothing.",
		position = 94,
		section = colorSection
	)
	default Color meatUsedColor()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "meatWastefulColor",
		name = "Meat: partly wasted",
		description = "Color of a meat's value when the next recharge takes it but the whistle needs "
			+ "fewer charges than it carries.",
		position = 95,
		section = colorSection
	)
	default Color meatWastefulColor()
	{
		return Color.YELLOW;
	}

	@ConfigItem(
		keyName = "meatUnusedColor",
		name = "Meat: not used",
		description = "Color of a meat's value when the whistle is already full before the next "
			+ "recharge reaches it.",
		position = 96,
		section = colorSection
	)
	default Color meatUnusedColor()
	{
		return Color.RED;
	}
}

