package com.quetzalcharges;

import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Draws the charge count on the whistle itself, matching the placement and font the built-in
 * Item Charges plugin uses so it looks native alongside it.
 */
class QuetzalChargesOverlay extends WidgetItemOverlay
{
	private final QuetzalChargesPlugin plugin;
	private final QuetzalChargesConfig config;

	@Inject
	QuetzalChargesOverlay(QuetzalChargesPlugin plugin, QuetzalChargesConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.showInventoryOverlay())
		{
			return;
		}

		final QuetzalWhistle whistle = QuetzalWhistle.byItemId(itemId);
		if (whistle == null)
		{
			return;
		}

		final int charges = plugin.getCharges(whistle);

		graphics.setFont(FontManager.getRunescapeSmallFont());

		final Rectangle bounds = widgetItem.getCanvasBounds();
		final TextComponent textComponent = new TextComponent();
		textComponent.setPosition(new Point(bounds.x - 1, bounds.y + 15));
		textComponent.setText(QuetzalChargesPlugin.formatCharges(whistle, charges));
		textComponent.setColor(plugin.getColor(whistle, charges));
		textComponent.render(graphics);
	}
}

