import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/**
 * Raw hunter meats that Soar Leader Pitri accepts, and the charges each one is worth.
 * <p>
 * Meat must be in the inventory unnoted and outside a meat pouch, so only inventory contents are
 * ever counted.
 */
@AllArgsConstructor
@Getter
enum HunterMeat
{
	QUETZAL_FEED(ItemID.VMQ2_QUETZAL_FEED, 1),
	RAW_WILD_KEBBIT(ItemID.HUNTINGBEAST_WILD_MEAT, 1),
	RAW_LARUPIA(ItemID.HUNTING_LARUPIA_MEAT, 1),
	RAW_BARB_TAILED_KEBBIT(ItemID.HUNTINGBEAST_BARBED_MEAT, 1),
	RAW_GRAAHK(ItemID.HUNTING_GRAAHK_MEAT, 2),
	RAW_KYATT(ItemID.HUNTING_KYATT_MEAT, 2),
	RAW_PYRE_FOX(ItemID.HUNTING_FENNECFOX_MEAT, 2),
	RAW_SUNLIGHT_ANTELOPE(ItemID.HUNTING_ANTELOPESUN_MEAT, 3),
	RAW_DASHING_KEBBIT(ItemID.HUNTINGBEAST_SPEEDY2_MEAT, 3),
	RAW_MOONLIGHT_ANTELOPE(ItemID.HUNTING_ANTELOPEMOON_MEAT, 3);

	private static final Map<Integer, HunterMeat> BY_ITEM_ID = new HashMap<>();

	static
	{
		for (HunterMeat meat : values())
		{
			BY_ITEM_ID.put(meat.itemId, meat);
		}
	}

	private final int itemId;
	private final int charges;

	@Nullable
	static HunterMeat byItemId(int itemId)
	{
		return BY_ITEM_ID.get(itemId);
	}
}

