import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Draws each hunter meat's charge value on it, colored by whether the next recharge would use it.
 * <p>
 * This is a plain {@link Overlay} rather than a {@code WidgetItemOverlay} like the whistle count
 * uses, and the reason is the whole feature. {@code WidgetItemOverlay} is built to answer "decorate
 * every instance of item X" -- it hands over an item id and a rectangle and deliberately says
 * nothing about position, because for its purpose position is noise. Here position is the entire
 * signal: Pitri consumes in slot order, so the second graahk in the inventory gets a different
 * verdict from the first even though they are the same item. Recovering the slot means walking the
 * inventory widget's children, where the child index is the slot.
 */
class QuetzalMeatOverlay extends Overlay
{
	private final Client client;
	private final QuetzalChargesPlugin plugin;
	private final QuetzalChargesConfig config;

	@Inject
	QuetzalMeatOverlay(Client client, QuetzalChargesPlugin plugin, QuetzalChargesConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showMeatValues())
		{
			return null;
		}

		final Widget inventory = client.getWidget(InterfaceID.Inventory.ITEMS);
		if (inventory == null || inventory.isHidden())
		{
			return null;
		}

		final Widget[] slots = inventory.getDynamicChildren();
		if (slots == null)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());
		final TextComponent text = new TextComponent();

		for (int slot = 0; slot < slots.length; slot++)
		{
			final Color color = plugin.getMeatColor(slot);
			if (color == null)
			{
				continue;
			}

			final int value = plugin.getMeatValue(slot);
			if (value <= 0)
			{
				continue;
			}

			// The slot's own index is trusted over its item id: the plugin built the prediction from
			// the same container in the same order, so slot N here is slot N there. Reading the id
			// back would only reintroduce the ambiguity between identical meats.
			final net.runelite.api.Point location = slots[slot].getCanvasLocation();
			if (location == null)
			{
				continue;
			}

			text.setPosition(new Point(location.getX() - 1, location.getY() + 10));
			text.setText(String.valueOf(value));
			text.setColor(color);
			text.render(graphics);
		}

		return null;
	}
}

