/**
 * Tracks quetzal whistle charges.
 * <p>
 * Charges are stored on the item, not in a player varbit, so there is nothing the client can read.
 * The game does however print the remaining count both when the whistle is checked and when it is
 * used to teleport, so that message carries the count on every event that spends one -- it is
 * treated as the truth and nothing is ever inferred on top of it.
 * <p>
 * The one gap is recharging at Soar Leader Pitri, which has no confirmed message. That is covered by
 * measuring the hunter meat the recharge consumed, since the conversion rate is fixed. A charge
 * message arriving first cancels that estimate, so the observed value always beats the computed one.
 * Until a whistle is seen the count is unknown and renders "?" rather than a guess.
 */
@Slf4j
@PluginDescriptor(
	name = "Quetzal Whistle Charges",
	description = "Shows remaining charges on quetzal whistles",
	tags = {"quetzal", "whistle", "charges", "varlamore", "hunter", "teleport", "rumour", "meat", "pitri"}
)
public class QuetzalChargesPlugin extends Plugin
{
	static final int UNKNOWN = -1;

	/**
	 * Printed both on "Check" and on a teleport, so it covers every charge that gets spent.
	 * Tier-agnostic: the game says "quetzal whistle" whichever tier is used. The optional "s" matters
	 * -- at one charge the message reads "has 1 charge remaining".
	 */
	private static final Pattern CHARGES_PATTERN = Pattern.compile(
		"Your quetzal whistle has (\\d+) charges? remaining");

	/**
	 * Printed by the whistle's "Rumour" option, which spends no charge:
	 * <p>
	 * <em>Your current rumour target is a grey chinchompa. You'll need to bring back some of its fur.
	 * Cervus was the source of the rumour.</em>
	 * <p>
	 * The target and the hunter are matched by separate patterns so that the sentence between them --
	 * which names whichever creature part is wanted and therefore varies with every rumour -- cannot
	 * cost us both if its wording ever changes. Non-greedy up to the first full stop, since the
	 * creature name is the only part with a fixed shape.
	 */
	private static final Pattern RUMOUR_TARGET_PATTERN = Pattern.compile(
		"Your current rumour target is (?:an?|the) (.+?)\\.");

	private static final Pattern RUMOUR_HUNTER_PATTERN = Pattern.compile(
		"(\\w+) was the source of the rumour");

	/**
	 * What the Rumour option prints with nothing assigned. Confirmed in-game 2026-08-07.
	 * <p>
	 * This is a stated fact, not an absence of one, so it is the single reliable way to know a stored
	 * rumour has gone stale without parsing guild dialogue in the Burrows. Worth one pattern.
	 */
	private static final Pattern NO_RUMOUR_PATTERN = Pattern.compile(
		"You do not have an active rumour");

	private static final String RUMOUR_TARGET_KEY = "rumourTarget";
	private static final String RUMOUR_HUNTER_KEY = "rumourHunter";

	private static final String RECHARGE_OPTION = "Recharge-whistle";

	/**
	 * Game ticks to keep watching the inventory for meat consumed by a recharge. Pitri takes meat
	 * until the whistle is full or the meat runs out, so charges gained equals charges consumed.
	 * Bounded because any other reason for meat leaving the inventory inside the window -- banking,
	 * cooking, dropping -- would be misread as a recharge.
	 * <p>
	 * 50 ticks is 30 seconds. The window has to outlast a human clicking through Pitri's dialogue,
	 * not just the server's response, and expiring early fails with no symptom at all. Arming
	 * requires an explicit Recharge-whistle click, so a wider window costs little.
	 */
	private static final int RECHARGE_WATCH_TICKS = 50;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private QuetzalChargesConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Notifier notifier;

	@Inject
	private QuetzalChargesOverlay overlay;

	@Inject
	private QuetzalMeatOverlay meatOverlay;

	private final Map<QuetzalWhistle, Integer> charges = new EnumMap<>(QuetzalWhistle.class);

	/** Whistles seen in the inventory last change, used to spot a tier upgrade. */
	private Set<QuetzalWhistle> lastInventoryWhistles = EnumSet.noneOf(QuetzalWhistle.class);

	private int meatCharges;
	private int rechargeWatchTicks;
	private int meatChargesAtRecharge;

	/** Whether the current recharge window has actually seen meat leave the inventory. */
	private boolean rechargeConsumedMeat;

	private static final int[] NO_MEAT_VALUES = new int[0];
	private static final MeatUse[] NO_MEAT_USES = new MeatUse[0];

	/** Charge value of the hunter meat in each inventory slot, 0 where the slot holds none. */
	private int[] meatValueBySlot = NO_MEAT_VALUES;

	/** What the next recharge would do with each slot, null where the slot holds no meat. */
	private MeatUse[] meatUseBySlot = NO_MEAT_USES;

	/** Whistle from the last menu click on one, used to attribute the count message to a tier. */
	@Nullable
	private QuetzalWhistle pendingWhistle;

	/**
	 * The rumour target the game last named, stored as the game's own words rather than mapped onto
	 * a creature enum. Nothing is done with it but print it back, so modelling it would mean keeping
	 * a table of every huntable creature in step with the game for no gain.
	 */
	@Nullable
	private String rumourTarget;

	/** The guild hunter the last rumour message credited, or null if it named none. */
	@Nullable
	private String rumourHunter;

	@Nullable
	private QuetzalChargesInfobox infobox;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(meatOverlay);

		// startUp runs on the AWT thread when the user toggles the plugin, but reading the inventory
		// and building the infobox image both assert the client thread. Hop over before touching them.
		clientThread.invokeLater(() ->
		{
			loadCharges();
			loadRumour();
			updateInventoryState();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(meatOverlay);
		removeInfobox();
		meatValueBySlot = NO_MEAT_VALUES;
		meatUseBySlot = NO_MEAT_USES;
		charges.clear();
		lastInventoryWhistles = EnumSet.noneOf(QuetzalWhistle.class);
		pendingWhistle = null;
		rumourTarget = null;
		rumourHunter = null;
		rechargeWatchTicks = 0;
		rechargeConsumedMeat = false;
		meatCharges = 0;
	}

	@Provides
	QuetzalChargesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(QuetzalChargesConfig.class);
	}

	// ------------------------------------------------------------------ events

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			// The RS profile is only resolved after login, so stored counts cannot be read earlier.
			loadCharges();
			loadRumour();
			updateInventoryState();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		final String message = Text.removeTags(event.getMessage());

		// Checked first because a rumour report and a charge count are mutually exclusive: the Rumour
		// option spends nothing, so it never prints a count alongside. Returning early keeps the two
		// paths from ever having to reason about each other.
		if (isNoRumourMessage(message))
		{
			clearRumour();
			updateInfobox();
			return;
		}

		final String target = parseRumourTarget(message);
		if (target != null)
		{
			setRumour(target, parseRumourHunter(message));
			updateInfobox();
			return;
		}

		final Integer reported = parseChargesMessage(message);
		if (reported == null)
		{
			return;
		}

		// A reported count is measured, so it supersedes any recharge still being estimated.
		rechargeWatchTicks = 0;

		final QuetzalWhistle whistle = pendingWhistle != null ? pendingWhistle : soleWhistleInInventory();
		pendingWhistle = null;

		if (whistle == null)
		{
			// Two different tiers are held and the click could not be attributed; leaving the counts
			// alone beats assigning the number to the wrong whistle.
			log.debug("Charge message with no attributable whistle");
			return;
		}

		setCharges(whistle, Math.min(reported, whistle.getMaxCharges()));
		refreshFromCharges();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Recharge is checked before the item, not after: the option name is the more specific
		// signal, and it is not certain whether the game hangs Recharge-whistle off Pitri or off the
		// whistle. If it is the whistle, an item-first test would match and swallow the click.
		if (RECHARGE_OPTION.equals(event.getMenuOption()))
		{
			rechargeWatchTicks = RECHARGE_WATCH_TICKS;
			meatChargesAtRecharge = meatCharges;
			rechargeConsumedMeat = false;
			log.debug("Recharge armed, baseline {} meat charges", meatChargesAtRecharge);
			return;
		}

		// Any click on a whistle -- Check, Signal, Last-destination -- may be followed by the count
		// message, so the tier is captured from the item rather than from the option name. Options
		// that produce no message (Drop, Rumour) simply leave the field unread.
		final QuetzalWhistle whistle = QuetzalWhistle.byItemId(event.getItemId());
		if (whistle != null)
		{
			pendingWhistle = whistle;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		updateInventoryState();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (rechargeWatchTicks > 0 && --rechargeWatchTicks == 0)
		{
			// Logged because a window that closes having seen nothing is otherwise completely
			// silent -- no charge change, no message, nothing in game.
			log.debug("Recharge window closed, consumed={} meat charges left={}",
				rechargeConsumedMeat, meatCharges);

			// Settled here rather than on the container change so that a recharge spread over
			// several inventory updates is judged on where it finished, not on its first step.
			settleRecharge();
			rechargeConsumedMeat = false;
			refreshFromCharges();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (QuetzalChargesConfig.GROUP.equals(event.getGroup()))
		{
			// Fired from whichever thread wrote the setting -- the settings panel is on AWT.
			clientThread.invokeLater(this::updateInfobox);
		}
	}

	// ------------------------------------------------------------- inventory

	private void updateInventoryState()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		final Set<QuetzalWhistle> whistles = EnumSet.noneOf(QuetzalWhistle.class);
		int meat = 0;

		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				final QuetzalWhistle whistle = QuetzalWhistle.byItemId(item.getId());
				if (whistle != null)
				{
					whistles.add(whistle);
					continue;
				}

				final HunterMeat hunterMeat = HunterMeat.byItemId(item.getId());
				if (hunterMeat != null)
				{
					meat += hunterMeat.getCharges() * item.getQuantity();
				}
			}
		}

		// applyUpgrade needs both the old and new sets; applyRecharge needs the new one, so the
		// field is swapped over between the two.
		applyUpgrade(whistles);
		lastInventoryWhistles = whistles;
		applyRecharge(meat);

		meatCharges = meat;

		// Last, because the prediction reads the charge count and applyRecharge may just have
		// changed it.
		updateMeatPrediction(inventory);

		updateInfobox();
	}

	/**
	 * Rebuilds everything downstream of the charge count, then redraws.
	 * <p>
	 * The meat prediction is a function of the count as much as of the inventory, so a path that
	 * moves the count has to rebuild it too -- {@link #updateInventoryState()} only runs on an
	 * inventory change and would not fire. A teleport is the case that exposes this: the count drops
	 * and the inventory does not move, so without this the verdicts would keep describing a recharge
	 * that is no longer the one in front of you.
	 */
	private void refreshFromCharges()
	{
		updateMeatPrediction(client.getItemContainer(InventoryID.INV));
		updateInfobox();
	}

	/**
	 * Works out, for every inventory slot, what the next recharge would do with the meat in it.
	 * <p>
	 * Pitri takes meat in slot order and stops once the whistle is full, without choosing meat that
	 * fits. So the last meat he takes is frequently worth more than the whistle still needs, and the
	 * surplus is lost -- which meat that is depends only on inventory order. Reordering the inventory
	 * is therefore a real saving, and showing it is the point of the overlay.
	 */
	private void updateMeatPrediction(@Nullable ItemContainer inventory)
	{
		final QuetzalWhistle whistle = heldWhistle();
		final int current = whistle == null ? UNKNOWN : getCharges(whistle);

		// Nothing to predict against without a whistle that can actually take charges and a count to
		// measure the shortfall from -- and nothing to predict once it is full, since a recharge that
		// cannot happen has no verdict on any meat. Rather than guess a shortfall, draw nothing at all.
		if (inventory == null || whistle == null || whistle.isInfinite() || current == UNKNOWN
			|| whistle.getMaxCharges() - current <= 0)
		{
			meatValueBySlot = NO_MEAT_VALUES;
			meatUseBySlot = NO_MEAT_USES;
			return;
		}

		final Item[] items = inventory.getItems();
		final int[] values = new int[items.length];

		for (int slot = 0; slot < items.length; slot++)
		{
			final HunterMeat meat = HunterMeat.byItemId(items[slot].getId());
			if (meat != null)
			{
				// Raw hunter meat does not stack, so a slot is one meat and quantity is not consulted.
				values[slot] = meat.getCharges();
			}
		}

		meatValueBySlot = values;
		meatUseBySlot = predictUse(values, whistle.getMaxCharges() - current);
	}

	/**
	 * The consumption model, kept free of client types so it can be tested directly.
	 *
	 * @param meatValues charge value per inventory slot, 0 where the slot holds no hunter meat
	 * @param needed     charges the whistle is short of full
	 * @return per-slot verdict, null where the slot holds no meat; empty when there is nothing to
	 *         predict at all, which is the signal to draw nothing rather than to draw a verdict
	 */
	static MeatUse[] predictUse(int[] meatValues, int needed)
	{
		// A full whistle is not "every meat unused" -- there is no recharge to reason about, so no
		// meat has a verdict. Saying UNUSED here would paint the whole inventory as waste, when the
		// honest answer is that the question does not arise.
		if (needed <= 0)
		{
			return NO_MEAT_USES;
		}

		final MeatUse[] uses = new MeatUse[meatValues.length];
		int running = 0;

		for (int slot = 0; slot < meatValues.length; slot++)
		{
			if (meatValues[slot] <= 0)
			{
				continue;
			}

			if (running >= needed)
			{
				uses[slot] = MeatUse.UNUSED;
				continue;
			}

			running += meatValues[slot];

			// Landing exactly on the requirement is not waste; overshooting it is. The overshoot can
			// only ever happen on the last meat taken, because the loop stops taking after that.
			uses[slot] = running <= needed ? MeatUse.USED : MeatUse.WASTEFUL;
		}

		return uses;
	}

	/**
	 * Crafting a higher tier consumes the old whistle and carries its charges over, so when a tier
	 * disappears in the same change that a better one appears, the count moves with it.
	 */
	private void applyUpgrade(Set<QuetzalWhistle> whistles)
	{
		for (QuetzalWhistle from : lastInventoryWhistles)
		{
			if (whistles.contains(from) || getCharges(from) == UNKNOWN)
			{
				continue;
			}

			for (QuetzalWhistle to : whistles)
			{
				if (to.ordinal() > from.ordinal() && !lastInventoryWhistles.contains(to))
				{
					if (!to.isInfinite())
					{
						setCharges(to, Math.min(getCharges(from), to.getMaxCharges()));
					}

					setCharges(from, UNKNOWN);
					return;
				}
			}
		}
	}

	/**
	 * Applies a running estimate while a recharge is in progress: the meat that vanished from the
	 * inventory is worth a known number of charges, so the count can move immediately.
	 * <p>
	 * This is only an estimate. Pitri wastes the remainder of the last meat he takes, so the meat
	 * consumed is an upper bound on the charges gained rather than an equality. The exact answer is
	 * settled when the window closes -- see {@link #settleRecharge()}.
	 */
	private void applyRecharge(int meat)
	{
		if (rechargeWatchTicks <= 0)
		{
			return;
		}

		final int consumed = meatChargesAtRecharge - meat;
		if (consumed <= 0)
		{
			// Meat unchanged or gained. The recharge has not landed yet, so hold the window open.
			return;
		}

		final QuetzalWhistle whistle = heldWhistle();
		if (whistle == null || whistle.isInfinite())
		{
			log.debug("Recharge of {} meat charges ignored, held whistle is {}", consumed, whistle);
			rechargeWatchTicks = 0;
			return;
		}

		rechargeConsumedMeat = true;

		// Re-baseline rather than closing the window, so a recharge that empties the inventory over
		// more than one container update is counted in full instead of only its first instalment.
		// The baseline moves with it, so nothing is counted twice.
		meatChargesAtRecharge = meat;

		final int current = getCharges(whistle);
		if (current == UNKNOWN)
		{
			// Nothing to add to. settleRecharge can still resolve this if meat is left over.
			log.debug("Recharge of {} meat charges not added, {} count is unknown", consumed, whistle);
			return;
		}

		setCharges(whistle, Math.min(current + consumed, whistle.getMaxCharges()));
	}

	/**
	 * Called once the recharge window closes, when the inventory has stopped moving.
	 * <p>
	 * Pitri stops for exactly two reasons: the whistle is full, or the meat ran out. So meat left
	 * over means the whistle is full -- an observation, not a sum. It does not depend on the previous
	 * count being known or on the meat-to-charge table being right, which makes it strictly better
	 * than the estimate {@link #applyRecharge} just made, and it is the common case.
	 * <p>
	 * If the meat ran out instead, the estimate is all there is and it stands.
	 */
	private void settleRecharge()
	{
		if (!rechargeConsumedMeat || meatCharges <= 0)
		{
			return;
		}

		final QuetzalWhistle whistle = heldWhistle();
		if (whistle == null || whistle.isInfinite())
		{
			return;
		}

		if (getCharges(whistle) != whistle.getMaxCharges())
		{
			log.debug("Recharge left {} meat charges spare, so {} is full", meatCharges, whistle);
			setCharges(whistle, whistle.getMaxCharges());
		}
	}

	/** Best tier currently in the inventory, or null if none is held. */
	@Nullable
	private QuetzalWhistle heldWhistle()
	{
		QuetzalWhistle best = null;
		for (QuetzalWhistle whistle : lastInventoryWhistles)
		{
			if (best == null || whistle.ordinal() > best.ordinal())
			{
				best = whistle;
			}
		}
		return best;
	}

	/** The only whistle in the inventory, or null when there are none or more than one tier. */
	@Nullable
	private QuetzalWhistle soleWhistleInInventory()
	{
		return lastInventoryWhistles.size() == 1 ? lastInventoryWhistles.iterator().next() : null;
	}

	// --------------------------------------------------------------- display

	/** Charge value of the meat in an inventory slot, or 0 if there is nothing to draw there. */
	int getMeatValue(int slot)
	{
		return slot >= 0 && slot < meatValueBySlot.length ? meatValueBySlot[slot] : 0;
	}

	/** Color for a slot's meat value, or null when that slot should not be drawn. */
	@Nullable
	Color getMeatColor(int slot)
	{
		if (slot < 0 || slot >= meatUseBySlot.length || meatUseBySlot[slot] == null)
		{
			return null;
		}

		switch (meatUseBySlot[slot])
		{
			case USED:
				return config.meatUsedColor();
			case WASTEFUL:
				return config.meatWastefulColor();
			default:
				return config.meatUnusedColor();
		}
	}

	static String formatCharges(QuetzalWhistle whistle, int charges)
	{
		if (whistle.isInfinite())
		{
			return "∞";
		}

		return charges == UNKNOWN ? "?" : String.valueOf(charges);
	}

	Color getColor(QuetzalWhistle whistle, int charges)
	{
		if (whistle.isInfinite() || charges == UNKNOWN)
		{
			return config.chargeColor();
		}

		if (charges == 0)
		{
			return config.emptyColor();
		}

		return charges <= config.lowChargeThreshold() ? config.lowChargeColor() : config.chargeColor();
	}

	private void updateInfobox()
	{
		final QuetzalWhistle whistle = heldWhistle();

		if (whistle == null || !config.showInfobox())
		{
			removeInfobox();
			return;
		}

		removeInfobox();

		final BufferedImage image = itemManager.getImage(whistle.getItemId());
		infobox = new QuetzalChargesInfobox(this, image, whistle, getCharges(whistle), buildTooltip(whistle));
		infoBoxManager.addInfoBox(infobox);
	}

	private void removeInfobox()
	{
		if (infobox != null)
		{
			infoBoxManager.removeInfoBox(infobox);
			infobox = null;
		}
	}

	private String buildTooltip(QuetzalWhistle whistle)
	{
		final StringBuilder tooltip = new StringBuilder(
			itemManager.getItemComposition(whistle.getItemId()).getName());

		if (config.showRechargeHelper() && !whistle.isInfinite() && meatCharges > 0)
		{
			tooltip.append("</br>Meat in inventory: ").append(meatCharges).append(" charges");

			final int current = getCharges(whistle);
			if (current != UNKNOWN)
			{
				tooltip.append("</br>To fill: ").append(whistle.getMaxCharges() - current);
			}
		}

		if (config.showRumour() && rumourTarget != null)
		{
			tooltip.append("</br>Rumour: ").append(capitalise(rumourTarget));

			if (rumourHunter != null)
			{
				tooltip.append(" (").append(rumourHunter).append(')');
			}
		}

		return tooltip.toString();
	}

	/**
	 * The game names the creature mid-sentence, so it arrives lowercase. Only the first letter is
	 * touched -- "sabre-toothed kyatt" is how the game writes it and title-casing would invent a
	 * spelling the game never used.
	 */
	static String capitalise(String text)
	{
		return text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	// ------------------------------------------------------------ persistence

	int getCharges(QuetzalWhistle whistle)
	{
		if (whistle.isInfinite())
		{
			return whistle.getMaxCharges();
		}

		final Integer value = charges.get(whistle);
		return value == null ? UNKNOWN : value;
	}

	private void setCharges(QuetzalWhistle whistle, int value)
	{
		final int previous = getCharges(whistle);
		log.debug("{} charges {} -> {}", whistle, previous, value);
		charges.put(whistle, value);
		configManager.setRSProfileConfiguration(QuetzalChargesConfig.GROUP, whistle.getConfigKey(), value);

		if (crossedLowThreshold(previous, value))
		{
			notifier.notify(config.lowChargeNotification(),
				"Your quetzal whistle has " + value + (value == 1 ? " charge" : " charges") + " remaining.");
		}
	}

	/** True only on the downward crossing, so the notification fires once rather than every use. */
	private boolean crossedLowThreshold(int previous, int current)
	{
		final int threshold = config.lowChargeThreshold();
		return previous != UNKNOWN && current != UNKNOWN && previous > threshold && current <= threshold;
	}

	private void loadCharges()
	{
		charges.clear();

		for (QuetzalWhistle whistle : QuetzalWhistle.values())
		{
			if (whistle.getConfigKey() == null)
			{
				continue;
			}

			final Integer stored = configManager.getRSProfileConfiguration(
				QuetzalChargesConfig.GROUP, whistle.getConfigKey(), Integer.class);

			if (stored != null)
			{
				charges.put(whistle, stored);
			}
		}
	}

	private void setRumour(String target, @Nullable String hunter)
	{
		log.debug("Rumour target {} from {}", target, hunter);
		rumourTarget = target;
		rumourHunter = hunter;

		configManager.setRSProfileConfiguration(QuetzalChargesConfig.GROUP, RUMOUR_TARGET_KEY, target);

		// Unset rather than store a placeholder, so a message that named no hunter cannot leave the
		// previous rumour's hunter sitting next to the new target.
		if (hunter == null)
		{
			configManager.unsetRSProfileConfiguration(QuetzalChargesConfig.GROUP, RUMOUR_HUNTER_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(QuetzalChargesConfig.GROUP, RUMOUR_HUNTER_KEY, hunter);
		}
	}

	private void clearRumour()
	{
		if (rumourTarget == null && rumourHunter == null)
		{
			return;
		}

		log.debug("Rumour cleared, was {} from {}", rumourTarget, rumourHunter);
		rumourTarget = null;
		rumourHunter = null;
		configManager.unsetRSProfileConfiguration(QuetzalChargesConfig.GROUP, RUMOUR_TARGET_KEY);
		configManager.unsetRSProfileConfiguration(QuetzalChargesConfig.GROUP, RUMOUR_HUNTER_KEY);
	}

	private void loadRumour()
	{
		rumourTarget = configManager.getRSProfileConfiguration(QuetzalChargesConfig.GROUP, RUMOUR_TARGET_KEY);
		rumourHunter = configManager.getRSProfileConfiguration(QuetzalChargesConfig.GROUP, RUMOUR_HUNTER_KEY);
	}

	/** Package-private for tests: the count in a charge message, or null if it is not one. */
	@Nullable
	static Integer parseChargesMessage(String message)
	{
		final Matcher matcher = CHARGES_PATTERN.matcher(message);
		return matcher.find() ? Integer.parseInt(matcher.group(1)) : null;
	}

	/** Package-private for tests: the rumour target in a Rumour message, or null if it is not one. */
	@Nullable
	static String parseRumourTarget(String message)
	{
		final Matcher matcher = RUMOUR_TARGET_PATTERN.matcher(message);
		return matcher.find() ? matcher.group(1) : null;
	}

	/** Package-private for tests: the hunter credited by a Rumour message, or null if it names none. */
	@Nullable
	static String parseRumourHunter(String message)
	{
		final Matcher matcher = RUMOUR_HUNTER_PATTERN.matcher(message);
		return matcher.find() ? matcher.group(1) : null;
	}

	/** Package-private for tests: whether the game just said there is no rumour assigned. */
	static boolean isNoRumourMessage(String message)
	{
		return NO_RUMOUR_PATTERN.matcher(message).find();
	}
}

