package com.quetzalcharges;

import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/**
 * The quetzal whistle tiers, ordered worst to best.
 * <p>
 * Charges are stored on the item itself rather than in a player varbit, so there is no value the
 * client can read directly. Each tier therefore keeps its own inferred count, and upgrading a
 * whistle carries the count across (the game preserves charges through the upgrade).
 */
@AllArgsConstructor
@Getter
enum QuetzalWhistle
{
	BASIC(ItemID.HG_QUETZALWHISTLE_BASIC, 5, "basicCharges"),
	ENHANCED(ItemID.HG_QUETZALWHISTLE_ENHANCED, 20, "enhancedCharges"),
	PERFECTED(ItemID.HG_QUETZALWHISTLE_PERFECTED, 50, "perfectedCharges"),
	/** Imbued whistle. Never runs down, so it has no stored count and no config key. */
	PERFECTED_INFINITE(ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE, Integer.MAX_VALUE, null);

	private static final Map<Integer, QuetzalWhistle> BY_ITEM_ID = new HashMap<>();

	static
	{
		for (QuetzalWhistle whistle : values())
		{
			BY_ITEM_ID.put(whistle.itemId, whistle);
		}
	}

	private final int itemId;
	private final int maxCharges;
	@Nullable
	private final String configKey;

	@Nullable
	static QuetzalWhistle byItemId(int itemId)
	{
		return BY_ITEM_ID.get(itemId);
	}

	boolean isInfinite()
	{
		return this == PERFECTED_INFINITE;
	}
}
